  "Histogram.Histogram#description": { hash: 'da2566d2', zh: "标题下面的一行——单位、时间窗口、需要提醒的地方。" },
  "Histogram.Histogram#className": { hash: '7b7fbc71', zh: "最后合并到 figure 上，所以调用处可以决定它的尺寸和间距。" },
