"Facet.Facet#showTitle": { hash: '2d8ba978', zh: "把标题印在网格上方，而不是藏起来。" },
  "Facet.Facet#description": { hash: 'da2566d2', zh: "标题下面的一行——单位、时间窗口、需要提醒的地方。" },
